const body = $('Webhook1').first().json.body || $('Webhook1').first().json;
const rawTarget = body.target ? body.target.trim() : '';
const rawEmail = body.email ? body.email.trim() : '';

let cleanTarget = rawTarget
  .replace(/^https?:\/\//i, '')
  .replace(/\/.*$/, '');

const ipRegex = /^(?:(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.){3}(?:25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$/;
const domainRegex = /^(?:[a-zA-Z0-9](?:[a-zA-Z0-9\-]{0,61}[a-zA-Z0-9])?\.)+[a-zA-Z]{2,}$/;
const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;

const isValidTarget = cleanTarget && (ipRegex.test(cleanTarget) || domainRegex.test(cleanTarget));
const isValidEmail = rawEmail && emailRegex.test(rawEmail);

if (!isValidTarget) {
  throw new Error(`Target non valido: "${rawTarget}".`);
}
if (!isValidEmail) {
  throw new Error(`Indirizzo email non valido: "${rawEmail}".`);
}

return [{
  json: {
    target: cleanTarget,
    original_target: rawTarget,
    email: rawEmail,
    validated_at: new Date().toISOString()
  }
}];

const target = $('Check Richiesta1').first().json.target;
const email = $('Check Richiesta1').first().json.email;

const testList = [
  { tipo: 'HEADER_SECURITY',      nome: 'Controllo Header di Sicurezza HTTP',       url: `https://${target}`,                                                           metodo: 'GET' },
  { tipo: 'EXPOSED_FILE',         nome: 'File di Configurazione (.env)',             url: `https://${target}/.env`,                                                       metodo: 'GET' },
  { tipo: 'EXPOSED_FILE',         nome: 'Repository Git Esposto (.git/HEAD)',        url: `https://${target}/.git/HEAD`,                                                  metodo: 'GET' },
  { tipo: 'EXPOSED_FILE',         nome: 'Backup Database Esposto (.sql)',            url: `https://${target}/backup.sql`,                                                 metodo: 'GET' },
  { tipo: 'EXPOSED_FILE',         nome: 'File di Configurazione (config.php)',       url: `https://${target}/config.php`,                                                 metodo: 'GET' },
  { tipo: 'EXPOSED_FILE',         nome: 'File wp-config.php (WordPress)',            url: `https://${target}/wp-config.php`,                                              metodo: 'GET' },
  { tipo: 'API_SWAGGER',          nome: 'Documentazione API / Swagger Esposta',      url: `https://${target}/swagger-ui.html`,                                            metodo: 'GET' },
  { tipo: 'INFO_DISCLOSURE',      nome: 'Information Disclosure (Header tecnologici)', url: `https://${target}`,                                                          metodo: 'GET' },
  { tipo: 'PATH_TRAVERSAL_LINUX', nome: 'Path Traversal Linux (/etc/passwd)',        url: `https://${target}/../../../../etc/passwd`,                                      metodo: 'GET' },
  { tipo: 'PATH_TRAVERSAL_WIN',   nome: 'Path Traversal Windows (win.ini)',          url: `https://${target}/..%5c..%5c..%5cwindows%5cwin.ini`,                           metodo: 'GET' },
  { tipo: 'SQL_INJECTION',        nome: 'SQL Injection (errori nel body)',           url: `https://${target}/?id=1'%20OR%20'1'='1`,                                       metodo: 'GET' },
  { tipo: 'XSS_REFLECTED',        nome: 'Cross-Site Scripting Riflesso (XSS)',       url: `https://${target}/?search=%3Cscript%3Econsole.log('XSS_TEST')%3C%2Fscript%3E`, metodo: 'GET' },
  { tipo: 'COMMAND_INJECTION',    nome: 'Command Injection (OS)',                   url: `https://${target}/?cmd=127.0.0.1%3Bwhoami`,                                    metodo: 'GET' },
  { tipo: 'DIRECTORY_LISTING',    nome: 'Directory Listing (cartella /uploads/)',    url: `https://${target}/uploads/`,                                                   metodo: 'GET' },
  { tipo: 'SSL_CHECK',            nome: 'Verifica HTTPS e Certificato SSL',          url: `https://${target}`,                                                            metodo: 'GET' }
];

return testList.map(test => ({
  json: {
    ...test,
    target: target,
    email: email
  }
}));

const responses = $input.all();
const originalTests = $('Simulate Attack1').all();

let score = 100;
let findings = [];
let detailedTests = [];

const target = $('Check Richiesta1').first().json.target || 'Target Sconosciuto';
const email = $('Check Richiesta1').first().json.email || '';

// Con HTTP Request v4.x + fullResponse=true la struttura è:
//   item.json = { statusCode: 200, headers: {...}, body: "..." }
originalTests.forEach((test, index) => {
  const original = test.json;
  const responseItem = responses[index] ? responses[index].json : {};

  // --- Estrazione corretta con fullResponse=true ---
  const statusCode = responseItem.statusCode || 0;
  const headers = responseItem.headers || {};
  // body può essere stringa o oggetto
  const rawBody = responseItem.body || '';
  const body = typeof rawBody === 'string' ? rawBody : JSON.stringify(rawBody);

  // Helper: normalizza gli header in lowercase (n8n li restituisce già lowercase ma sicurezza extra)
  const h = (name) => headers[name.toLowerCase()] || '';

  // ============================================================
  // HEADER_SECURITY - controlla gli header di sicurezza HTTP
  // ============================================================
  if (original.tipo === 'HEADER_SECURITY') {
    let missingCount = 0;
    let headerIssues = [];

    if (!h('strict-transport-security')) {
      score -= 5;
      findings.push('[LIEVE] Manca header HSTS (Strict-Transport-Security).');
      headerIssues.push('HSTS');
      missingCount++;
    }
    if (!h('content-security-policy')) {
      score -= 10;
      findings.push('[MEDIO] Manca header Content-Security-Policy (CSP).');
      headerIssues.push('CSP');
      missingCount++;
    }
    if (!h('x-frame-options')) {
      score -= 5;
      findings.push('[LIEVE] Manca header X-Frame-Options.');
      headerIssues.push('X-Frame-Options');
      missingCount++;
    }
    if (!h('x-content-type-options')) {
      score -= 5;
      findings.push('[LIEVE] Manca header X-Content-Type-Options.');
      headerIssues.push('X-Content-Type-Options');
      missingCount++;
    }
    if (!h('referrer-policy')) {
      score -= 3;
      findings.push('[LIEVE] Manca header Referrer-Policy.');
      headerIssues.push('Referrer-Policy');
      missingCount++;
    }
    if (!h('permissions-policy') && !h('feature-policy')) {
      score -= 3;
      findings.push('[LIEVE] Manca header Permissions-Policy.');
      headerIssues.push('Permissions-Policy');
      missingCount++;
    }

    if (statusCode === 0) {
      detailedTests.push({ nome: original.nome, esito: '⚠️ Nessuna risposta ricevuta (timeout o errore)' });
    } else if (missingCount > 0) {
      detailedTests.push({ nome: original.nome, esito: `⚠️ ${missingCount} header mancanti: ${headerIssues.join(', ')}` });
    } else {
      detailedTests.push({ nome: original.nome, esito: '✅ Ottimale (tutti gli header presenti)' });
    }
  }

  // ============================================================
  // EXPOSED_FILE - file sensibili esposti (NO redirect)
  // ============================================================
  if (original.tipo === 'EXPOSED_FILE') {
    // Con followRedirects=false, un 301/302 non viene contato come "esposto"
    // Solo 200 diretto è un vero problema
    if (statusCode === 200) {
      score -= 20;
      findings.push(`[ALTO] Risorsa sensibile esposta pubblicamente: ${original.url}`);
      detailedTests.push({ nome: original.nome, esito: `🚨 Esposto (200 OK)` });
    } else if (statusCode >= 301 && statusCode <= 302) {
      detailedTests.push({ nome: original.nome, esito: `ℹ️ Reindirizzamento (${statusCode}) - non direttamente esposto` });
    } else {
      detailedTests.push({ nome: original.nome, esito: `✅ Protetto (${statusCode})` });
    }
  }

  // ============================================================
  // API_SWAGGER - documentazione API esposta
  // ============================================================
  if (original.tipo === 'API_SWAGGER') {
    const swaggerPaths = [
      '/swagger-ui.html', '/swagger-ui/', '/api-docs',
      '/v2/api-docs', '/v3/api-docs', '/openapi.json', '/swagger.json'
    ];
    const bodyLower = body.toLowerCase();
    const isSwaggerBody = bodyLower.includes('swagger') || bodyLower.includes('openapi') || bodyLower.includes('api-docs');

    if (statusCode === 200 && isSwaggerBody) {
      score -= 15;
      findings.push(`[MEDIO] Documentazione API/Swagger esposta: ${original.url}`);
      detailedTests.push({ nome: original.nome, esito: '⚠️ Swagger/API docs esposti (200 OK)' });
    } else if (statusCode === 200) {
      // 200 ma corpo non swagger - potrebbe essere pagina di login o redirect applicativo
      detailedTests.push({ nome: original.nome, esito: `ℹ️ Risposta 200 ma non sembra Swagger` });
    } else {
      detailedTests.push({ nome: original.nome, esito: `✅ Non trovato / Protetto (${statusCode})` });
    }
  }

  // ============================================================
  // INFO_DISCLOSURE - header che rivelano tecnologie
  // ============================================================
  if (original.tipo === 'INFO_DISCLOSURE') {
    const serverHeader = h('server');
    const poweredBy = h('x-powered-by');
    const aspNet = h('x-aspnet-version');
    const aspNetMvc = h('x-aspnetmvc-version');

    let disclosed = [];
    if (serverHeader) disclosed.push(`Server: ${serverHeader}`);
    if (poweredBy) disclosed.push(`X-Powered-By: ${poweredBy}`);
    if (aspNet) disclosed.push(`X-AspNet-Version: ${aspNet}`);
    if (aspNetMvc) disclosed.push(`X-AspNetMvc-Version: ${aspNetMvc}`);

    if (disclosed.length > 0) {
      score -= 5;
      findings.push(`[LIEVE] Information Disclosure: ${disclosed.join(', ')}`);
      detailedTests.push({ nome: original.nome, esito: `⚠️ Header tecnologici esposti: ${disclosed.join(', ')}` });
    } else {
      detailedTests.push({ nome: original.nome, esito: '✅ Nessuna informazione tecnica esposta' });
    }
  }

  // ============================================================
  // PATH_TRAVERSAL_LINUX
  // ============================================================
  if (original.tipo === 'PATH_TRAVERSAL_LINUX') {
    const isVulnerable = statusCode === 200 && (
      body.includes('root:x:0:0') ||
      body.includes('root:!:') ||
      body.includes('/bin/bash') ||
      body.includes('/bin/sh')
    );
    if (isVulnerable) {
      score -= 30;
      findings.push(`[CRITICO] Vulnerabile a Path Traversal Linux: ${original.url}`);
      detailedTests.push({ nome: original.nome, esito: '🚨 Vulnerabile - /etc/passwd accessibile' });
    } else {
      detailedTests.push({ nome: original.nome, esito: `✅ Sicuro (${statusCode})` });
    }
  }

  // ============================================================
  // PATH_TRAVERSAL_WIN
  // ============================================================
  if (original.tipo === 'PATH_TRAVERSAL_WIN') {
    const isVulnerable = statusCode === 200 && (
      body.includes('[extensions]') ||
      body.includes('[fonts]') ||
      body.includes('[mci extensions]') ||
      body.toLowerCase().includes('for 16-bit app support')
    );
    if (isVulnerable) {
      score -= 30;
      findings.push(`[CRITICO] Vulnerabile a Path Traversal Windows: ${original.url}`);
      detailedTests.push({ nome: original.nome, esito: '🚨 Vulnerabile - win.ini accessibile' });
    } else {
      detailedTests.push({ nome: original.nome, esito: `✅ Sicuro (${statusCode})` });
    }
  }

  // ============================================================
  // SQL_INJECTION - ricerca errori SQL nel body
  // ============================================================
  if (original.tipo === 'SQL_INJECTION') {
    const sqlErrors = [
      /you have an error in your sql syntax/i,
      /unclosed quotation mark/i,
      /sqlite3::/i,
      /pg_query\(\)/i,
      /ORA-\d{5}/,                           // Oracle
      /Microsoft OLE DB Provider for SQL/i,
      /Incorrect syntax near/i,
      /mysql_fetch_array\(\)/i,
      /supplied argument is not a valid MySQL/i,
      /Warning.*mysql_.*\(\)/i,
      /valid MySQL result/i,
      /MySqlException/i,
      /SqlException/i
    ];
    const isVulnerable = statusCode === 200 && sqlErrors.some(rx => rx.test(body));
    if (isVulnerable) {
      score -= 30;
      findings.push(`[CRITICO] Possibile SQL Injection rilevato: ${original.url}`);
      detailedTests.push({ nome: original.nome, esito: '🚨 Vulnerabile - errori SQL nel body' });
    } else {
      detailedTests.push({ nome: original.nome, esito: `✅ Sicuro (${statusCode})` });
    }
  }

  // ============================================================
  // XSS_REFLECTED - payload XSS riflesso nel body
  // ============================================================
  if (original.tipo === 'XSS_REFLECTED') {
    // Controlla se il payload (decodificato) viene riflesso nel body
    const xssPayload = "<script>console.log('XSS_TEST')</script>";
    const isVulnerable = statusCode === 200 && body.includes(xssPayload);
    if (isVulnerable) {
      score -= 20;
      findings.push(`[ALTO] Reflected XSS rilevato: ${original.url}`);
      detailedTests.push({ nome: original.nome, esito: '🚨 Vulnerabile - payload XSS riflesso' });
    } else {
      detailedTests.push({ nome: original.nome, esito: `✅ Sicuro (${statusCode})` });
    }
  }

  // ============================================================
  // COMMAND_INJECTION
  // ============================================================
  if (original.tipo === 'COMMAND_INJECTION') {
    const rcePatterns = [
      /uid=\d+.*gid=\d+/i,
      /root:x:0:0/,
      /www-data/,
      /nt authority/i,
      /WINDOWS\\system32/i
    ];
    const isVulnerable = statusCode === 200 && rcePatterns.some(rx => rx.test(body));
    if (isVulnerable) {
      score -= 35;
      findings.push(`[CRITICO] Command Injection rilevato: ${original.url}`);
      detailedTests.push({ nome: original.nome, esito: '🚨 Vulnerabile - output di sistema nel body' });
    } else {
      detailedTests.push({ nome: original.nome, esito: `✅ Sicuro (${statusCode})` });
    }
  }

  // ============================================================
  // DIRECTORY_LISTING
  // ============================================================
  if (original.tipo === 'DIRECTORY_LISTING') {
    const isListing = statusCode === 200 && (
      body.includes('Index of /') ||
      body.includes('<title>Index of') ||
      body.includes('Directory listing for') ||
      /\[DIR\].*Parent Directory/i.test(body)
    );
    if (isListing) {
      score -= 15;
      findings.push(`[MEDIO] Directory Listing attivo: ${original.url}`);
      detailedTests.push({ nome: original.nome, esito: '⚠️ Directory Listing attivo' });
    } else {
      detailedTests.push({ nome: original.nome, esito: `✅ Disabilitato (${statusCode})` });
    }
  }

  // ============================================================
  // SSL_CHECK - HTTPS funzionante
  // ============================================================
  if (original.tipo === 'SSL_CHECK') {
    if (statusCode >= 200 && statusCode < 400) {
      // Controlla se HSTS è presente come bonus
      const hasHSTS = !!h('strict-transport-security');
      detailedTests.push({
        nome: original.nome,
        esito: hasHSTS ? '✅ HTTPS operativo + HSTS attivo' : '✅ HTTPS operativo (HSTS assente)'
      });
    } else if (statusCode === 0) {
      score -= 20;
      findings.push('[ALTO] Impossibile raggiungere il server via HTTPS - potrebbe non supportarlo.');
      detailedTests.push({ nome: original.nome, esito: '🚨 HTTPS non raggiungibile (timeout o errore SSL)' });
    } else {
      score -= 15;
      findings.push(`[MEDIO] HTTPS risponde con status anomalo: ${statusCode}`);
      detailedTests.push({ nome: original.nome, esito: `⚠️ HTTPS anomalo (${statusCode})` });
    }
  }
});

score = Math.max(0, score);

const livello = score >= 80 ? 'SICURO' : score >= 50 ? 'A RISCHIO' : 'CRITICO';

return [{
  json: {
    target: target,
    email: email,
    esito: livello,
    punteggio: `${score}/100`,
    punteggio_numerico: score,
    vulnerabilita_trovate: findings.length,
    dettagli_vulnerabilita: findings,
    dettagli_test: detailedTests,
    data_scansione: new Date().toLocaleString('it-IT')
  }
}];

